WITH RECURSIVE c(n, v) AS (SELECT 1, 7 UNION ALL SELECT n + 1, (v * 1170 + 12345) % 1000003 FROM c WHERE n < 37290) SELECT count(*), sum(v), max(v) FROM c;
WITH RECURSIVE f(n, a, b) AS (SELECT 1, 0, 1 UNION ALL SELECT n + 1, b, (a + b) % 1000000007 FROM f WHERE n < 23563) SELECT a FROM f ORDER BY n DESC LIMIT 1;
